#[derive(Clone)]
struct FakeBrowser {
    observation: Observation,
    applied: Arc<Mutex<Vec<Action>>>,
}

impl FakeBrowser {
    fn new(observation: Observation) -> Self {
        Self {
            observation,
            applied: Arc::new(Mutex::new(Vec::new())),
        }
    }
}

#[async_trait]
impl Browser for FakeBrowser {
    async fn snapshot(&self) -> Result<Observation, BrowserError> {
        Ok(self.observation.clone())
    }

    async fn apply(&self, action: &Action) -> Result<StepResult, BrowserError> {
        self.applied.lock().await.push(action.clone());
        Ok(StepResult {
            ok: true,
            error: None,
            new_state_hash: None,
            scroll: None,
            extract: None,
        })
    }

    async fn shutdown(&self) -> Result<(), BrowserError> {
        Ok(())
    }
}

#[derive(Clone)]
struct UsageLlm {
    usage: TokenUsage,
}

#[async_trait]
impl LlmClient for UsageLlm {
    async fn propose_action(
        &self,
        _task: &str,
        _plan: Option<&str>,
        _observation: &Observation,
        _observations: &VecDeque<Observation>,
        _history: &[Action],
        _steps: &[StepRecord],
    ) -> Result<LlmResponse, LlmError> {
        Ok(LlmResponse {
            action: Action::Done {
                summary: "ok".to_string(),
            },
            usage: Some(self.usage.clone()),
        })
    }
}

